 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # Large color fields are the underlying picture; rare colors are speckle.
    base = {color for color, n in counts.items() if n >= max(6, h * w // 100)}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            vals = [grid[y][x] for y in range(max(0, r - 1), min(h, r + 2))
                    for x in range(max(0, c - 1), min(w, c + 2))
                    if grid[y][x] in base]
            if not vals:
                continue
            local = Counter(vals)
            best, n = local.most_common(1)[0]
            current = grid[r][c]
            # Replace isolated non-base marks, and fill background holes only
            # when a non-background field has a strict local majority.
            if current not in base:
                out[r][c] = best
            elif current == bg and best != bg and n > local.get(bg, 0):
                out[r][c] = best
    return out


