 "content": "from collections import Counter


def _rectangles(mask, min_density=0.78):
    h, w = len(mask), len(mask[0])
    # Enumerate rectangles using row-pair sums; select the densest large
    # rectangles first, then remove their support before finding the next.
    remaining = [row[:] for row in mask]
    found = []
    while True:
        integral = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                run += remaining[r][c]
                integral[r + 1][c + 1] = integral[r][c + 1] + run
        best = None
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1-r0+1)*(c1-c0+1)
                        s = integral[r1+1][c1+1]-integral[r0][c1+1]-integral[r1+1][c0]+integral[r0][c0]
                        density = s / area
                        if density >= min_density and area >= 4:
                            # Prefer substantial, near-solid patches.
                            score = area * density
                            if best is None or score > best[0]:
                                best = (score, r0, r1, c0, c1)
        if best is None:
            break
        _, r0, r1, c0, c1 = best
        found.append((r0, r1, c0, c1))
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                remaining[r][c] = 0
    return found


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
