 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v != bg}

    for color in colors:
        active = [[grid[r][c] == color for c in range(w)] for r in range(h)]
        while True:
            # Integral image lets us score candidate rectangular objects.
            integ = [[0] * (w + 1) for _ in range(h + 1)]
            for r in range(h):
                run = 0
                for c in range(w):
                    run += active[r][c]
                    integ[r + 1][c + 1] = integ[r][c + 1] + run
            best = None
            for r0 in range(h - 1):
                for r1 in range(r0 + 1, h):
                    for c0 in range(w - 1):
                        for c1 in range(c0 + 1, w):
                            area = (r1-r0+1)*(c1-c0+1)
                            if area < 6:
                                continue
                            n = (integ[r1+1][c1+1] - integ[r0][c1+1]
                                 - integ[r1+1][c0] + integ[r0][c0])
                            density = n / area
                            if density < 0.72:
                                continue
                            score = area * density
                            if best is None or score > best[0]:
                                best = (score, r0, r1, c0, c1)
            if best is None:
                break
            _, r0, r1, c0, c1 = best
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    out[r][c] = color
                    active[r][c] = False
    return out


