def transform(grid):
    """Keep only solid rectangular objects; remove all sparse distractors."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    # Objects are the large, repeated colors; isolated rare colors are marks.
    object_colors = {color for color, n in counts.items() if color != bg and n >= 8}
    for color in object_colors:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
                r0 = min(y for y, x in cells)
                r1 = max(y for y, x in cells)
                c0 = min(x for y, x in cells)
                c1 = max(x for y, x in cells)
                area = (r1-r0+1) * (c1-c0+1)
                if r1 > r0 and c1 > c0 and len(cells) >= 6 and len(cells)/area >= 0.70:
                    for y in range(r0, r1+1):
                        for x in range(c0, c1+1):
                            out[y][x] = color
    return out


